import subprocess
def kept(seed, frac_str, n=5):
    fa = "".join([f">s{i}\nACGT\n" for i in range(n)])
    r=subprocess.run(["./executable","seq","-f",frac_str,"-s",str(seed)], input=fa, capture_output=True, text=True)
    out=r.stdout
    kept=set()
    for line in out.splitlines():
        if line.startswith(">"):
            kept.add(line[1:].split()[0])
    return kept

def find_rand_precise(seed, idx, n=5, iters=40):
    lo,hi=0.0,1.0
    for _ in range(iters):
        mid=(lo+hi)/2
        # format with high precision
        frac_str=repr(mid)
        k=kept(seed, frac_str, n)
        if f"s{idx}" in k:
            hi=mid
        else:
            lo=mid
    return (lo+hi)/2, lo, hi

