#include <iostream>
#include <random>
#include <fstream>
#include <string>
#include <vector>
#include <cstdlib>
int main(){
    std::ifstream f("/tmp/randbits.txt");
    std::string s; f>>s;
    std::vector<int> t;
    for(char c: s) t.push_back(c-'0');
    int n=t.size();
    std::vector<long long> seeds={11,0,1,42,12345,123456789,987654321,0x12345678,1234567,999,1000,2024,2025,123,456,789,1000000};
    for(long long seed: seeds){
        // mt19937_64 lowbit/highbit
        {
            std::mt19937_64 rng(seed);
            int m_low=0,m_high=0;
            for(int i=0;i<n;i++){ uint64_t v=rng(); if((v&1)==t[i]) m_low++; if(((v>>63)&1)==t[i]) m_high++; }
            if(m_low>=80||m_high>=80) std::cout<<"mt64 seed "<<seed<<" low "<<m_low<<" high "<<m_high<<"\n";
        }
        // mt19937
        {
            std::mt19937 rng((uint32_t)seed);
            int m_low=0,m_high=0;
            for(int i=0;i<n;i++){ uint32_t v=rng(); if((v&1)==t[i]) m_low++; if(((v>>31)&1)==t[i]) m_high++; }
            if(m_low>=80||m_high>=80) std::cout<<"mt32 seed "<<seed<<" low "<<m_low<<" high "<<m_high<<"\n";
        }
        // rand
        {
            srand(seed);
            int m_low=0,m_high=0;
            for(int i=0;i<n;i++){ int r=rand(); if((r&1)==t[i]) m_low++; if(((r>>30)&1)==t[i]) m_high++; }
            if(m_low>=80||m_high>=80) std::cout<<"rand seed "<<seed<<" low "<<m_low<<" high "<<m_high<<"\n";
        }
        // lrand48
        {
            srand48(seed);
            int m_low=0,m_high=0;
            for(int i=0;i<n;i++){ long r=lrand48(); if((r&1)==t[i]) m_low++; if(((r>>30)&1)==t[i]) m_high++; }
            if(m_low>=80||m_high>=80) std::cout<<"lrand48 seed "<<seed<<" low "<<m_low<<" high "<<m_high<<"\n";
        }
        // drand48
        {
            srand48(seed);
            int m=0;
            for(int i=0;i<n;i++){ int bit=(drand48()<0.5)?0:1; if(bit==t[i]) m++; }
            if(m>=80) std::cout<<"drand48 seed "<<seed<<" high "<<m<<"\n";
        }
    }
    std::cout<<"done\n";
    return 0;
}
